package openai

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"regexp"
	"sort"
	"strings"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/modelmatch"
	"github.com/DocumentDrivenDX/fizeau/internal/sdk/openaicompat"
)

// ScoredModel is a discovered model with a selection preference score.
// Higher scores are preferred by the auto-selection logic.
type ScoredModel struct {
	// ID is the model identifier returned by the server's /v1/models endpoint.
	ID string
	// CatalogRef is the catalog target ID if this model is recognized in the
	// model catalog for the provider's surface. Empty for unrecognized models.
	CatalogRef string
	// PatternMatch is true when this model matched the configured model_pattern.
	PatternMatch bool
	// Score summarises the selection preference: 3 = catalog-recognized,
	// 2 = pattern-matched, 1 = uncategorized.
	Score int
}

// DiscoverModels queries the generic /v1/models endpoint through the shared
// OpenAI-compatible SDK. It is kept here as a package-level compatibility
// wrapper for existing provider tests and callers inside this package.
func DiscoverModels(ctx context.Context, baseURL, apiKey string) ([]string, error) {
	return openaicompat.DiscoverModels(ctx, baseURL, apiKey)
}

// RankModels scores and sorts a list of discovered model IDs by selection
// preference:
//
//   - Score 3 — catalog-recognized: the model ID appears in knownModels (a map
//     from concrete model ID to catalog target ID, e.g. from
//     Catalog.AllConcreteModels). These are explicitly tracked models; prefer
//     them when auto-selecting.
//   - Score 2 — pattern-matched: the model ID matches the case-insensitive
//     pattern regex (pattern == "" means this tier is skipped).
//   - Score 1 — uncategorized: known to the server but not in the catalog or
//     pattern.
//
// Within each score tier, the original server-returned order is preserved.
// Returns an error only if pattern is non-empty and fails to compile.
func RankModels(candidates []string, knownModels map[string]string, pattern string) ([]ScoredModel, error) {
	var patternRe *regexp.Regexp
	if pattern != "" {
		re, err := regexp.Compile("(?i)" + pattern)
		if err != nil {
			return nil, fmt.Errorf("discovery: invalid model_pattern %q: %w", pattern, err)
		}
		patternRe = re
	}

	scored := make([]ScoredModel, 0, len(candidates))
	for _, id := range candidates {
		sm := ScoredModel{ID: id, Score: 1}
		if ref, ok := knownModels[id]; ok {
			sm.CatalogRef = ref
			sm.Score = 3
		} else if patternRe != nil && patternRe.MatchString(id) {
			sm.PatternMatch = true
			sm.Score = 2
		}
		scored = append(scored, sm)
	}

	// Stable sort: higher score first, original order preserved within tier.
	sort.SliceStable(scored, func(i, j int) bool {
		return scored[i].Score > scored[j].Score
	})
	return scored, nil
}

// SelectModel picks the preferred model ID from a ranked list. Returns ""
// if the list is empty.
func SelectModel(ranked []ScoredModel) string {
	if len(ranked) == 0 {
		return ""
	}
	return ranked[0].ID
}

// getAndDecode performs a GET request with optional Bearer auth and extra
// headers, decodes the JSON response into out, and returns any error.
func getAndDecode(ctx context.Context, timeout time.Duration, endpoint, apiKey string, headers map[string]string, out any) error {
	reqCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	req, err := http.NewRequestWithContext(reqCtx, http.MethodGet, endpoint, nil)
	if err != nil {
		return err
	}
	req.Header.Set("Accept", "application/json")
	if apiKey != "" {
		req.Header.Set("Authorization", "Bearer "+apiKey)
	}
	for k, v := range headers {
		req.Header.Set(k, v)
	}

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close() //nolint:errcheck

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
		return fmt.Errorf("HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	return json.NewDecoder(resp.Body).Decode(out)
}

// MatchModelIDs returns every catalog entry whose normalized form contains
// the normalized request as a substring. Normalization lowercases, strips a
// single leading vendor namespace, and removes all non-alphanumeric
// separators, so "qwen/qwen3.6" and "Qwen3.6" and "qwen3.6" all match
// "Qwen3.6-35B-A3B-4bit" and "Qwen3.6-35B-A3B-nvfp4".
//
// The returned slice preserves original catalog case and order. An empty slice
// means no match; callers are responsible for deciding whether to pass the
// original request through to the provider unchanged or to escalate.
//
// This is the primary matching primitive since v0.9.2 — it replaces the
// scalar logic previously in NormalizeModelID. NormalizeModelID is retained
// as a backward-compatible wrapper.
func MatchModelIDs(requested string, catalog []string) []string {
	return modelmatch.Match(requested, catalog)
}

// NormalizeModelID resolves a caller-supplied model name against the server's
// canonical model catalog (the IDs returned by GET /v1/models).
//
// Prefer MatchModelIDs for new code; this wrapper is retained for backward
// compatibility with the v0.9.1 call signature. Behaviour:
//   - 0 matches → returns the original requested string, no error
//   - 1 match   → returns the catalog entry, no error
//   - 2+ matches → returns "" and an ambiguity error listing the candidates
func NormalizeModelID(requested string, catalog []string) (string, error) {
	if strings.TrimSpace(requested) == "" {
		return requested, nil
	}
	matches := MatchModelIDs(requested, catalog)
	switch len(matches) {
	case 0:
		return requested, nil
	case 1:
		return matches[0], nil
	default:
		return "", fmt.Errorf("ambiguous model %q: matches %v", requested, matches)
	}
}

// Package routing implements the unified routing engine for fizeau.
// It ranks (harness, provider, model) candidates uniformly per CONTRACT-003.
//
// The engine consolidates DDx-side harness-tier routing and agent-side
// per-provider failover into a single ranking pipeline.
package routing

import (
	"strings"
)

// canonicalizeModelKey strips a single leading vendor namespace (e.g.
// "qwen/qwen3.6" → "qwen3.6") and lowercases the result. Only the first
// slash-segment is stripped so multi-segment paths like "openai/o1/preview"
// become "o1/preview", not "preview".
//
// Fixes ddx-0486e601: case + vendor-prefix normalization so that
// "qwen/qwen3.6" can match "Qwen3.6-35B-A3B-4bit".
func canonicalizeModelKey(s string) string {
	s = strings.TrimSpace(s)
	if slash := strings.Index(s, "/"); slash > 0 {
		s = s[slash+1:]
	}
	return strings.ToLower(s)
}

// FuzzyMatch returns the best concrete model from pool for the given input,
// using canonical-form (case-insensitive, vendor-prefix-stripped) matching.
// Returns "" when no candidate matches.
//
// Algorithm:
//  1. Exact match (case-insensitive on canonical form) wins outright.
//  2. Prefix/suffix/contains match on canonical form. Among fuzzy matches,
//     prefer prefix, then suffix, then contains, and within each tier prefer
//     the shortest remaining text (most specific match).
//  3. No match returns "".
func FuzzyMatch(input string, pool []string) string {
	if input == "" || len(pool) == 0 {
		return ""
	}
	cInput := canonicalizeModelKey(input)
	if cInput == "" {
		return ""
	}
	if best := bestQwenFamilyMatch(cInput, pool); best != "" {
		return best
	}

	// Pass 1: exact canonical match.
	for _, m := range pool {
		if canonicalizeModelKey(m) == cInput {
			return m
		}
	}

	// Pass 2: canonical prefix/suffix/contains match. Track the candidate with
	// the best tier and then the shortest remaining text.
	var best string
	bestTier := 4
	bestRemainder := -1
	for _, m := range pool {
		cm := canonicalizeModelKey(m)
		if len(cm) <= len(cInput) || !strings.Contains(cm, cInput) {
			continue
		}
		tier := 3
		switch {
		case strings.HasPrefix(cm, cInput):
			tier = 1
		case strings.HasSuffix(cm, cInput):
			tier = 2
		}
		remainder := len(cm) - len(cInput)
		if tier < bestTier || (tier == bestTier && (bestRemainder < 0 || remainder < bestRemainder)) {
			best = m
			bestTier = tier
			bestRemainder = remainder
		}
	}
	return best
}

func bestQwenFamilyMatch(input string, pool []string) string {
	if input != "qwen" && !strings.HasPrefix(input, "qwen3") && !strings.HasPrefix(input, "qwen-3") {
		return ""
	}
	var best string
	var bestVersion []int
	bestParams := -1
	bestVariant := -1
	for _, model := range pool {
		candidate := canonicalizeModelKey(model)
		if !strings.Contains(candidate, input) {
			continue
		}
		version, params, variant, ok := parseQwenRank(candidate)
		if !ok {
			continue
		}
		if best == "" || compareQwenRank(version, params, variant, bestVersion, bestParams, bestVariant) > 0 {
			best = model
			bestVersion = version
			bestParams = params
			bestVariant = variant
		}
	}
	return best
}

func parseQwenRank(model string) ([]int, int, int, bool) {
	if !strings.Contains(model, "qwen") {
		return nil, 0, 0, false
	}
	idx := strings.Index(model, "qwen")
	rest := model[idx+len("qwen"):]
	rest = strings.TrimPrefix(rest, "-")
	version := make([]int, 0, 2)
	for len(rest) > 0 {
		if rest[0] < '0' || rest[0] > '9' {
			break
		}
		n := 0
		for len(rest) > 0 && rest[0] >= '0' && rest[0] <= '9' {
			n = n*10 + int(rest[0]-'0')
			rest = rest[1:]
		}
		version = append(version, n)
		if len(rest) == 0 || (rest[0] != '.' && rest[0] != '-') {
			break
		}
		if len(rest) > 1 && rest[1] >= '0' && rest[1] <= '9' {
			rest = rest[1:]
			continue
		}
		break
	}
	if len(version) == 0 {
		return nil, 0, 0, false
	}
	params := qwenParamBillions(model)
	return version, params, qwenVariantRank(model), true
}

func qwenParamBillions(model string) int {
	best := -1
	for i := 0; i < len(model); i++ {
		if model[i] < '0' || model[i] > '9' {
			continue
		}
		n := 0
		j := i
		for j < len(model) && model[j] >= '0' && model[j] <= '9' {
			n = n*10 + int(model[j]-'0')
			j++
		}
		if j < len(model) && model[j] == 'b' && n > best {
			best = n
		}
		i = j
	}
	return best
}

func qwenVariantRank(model string) int {
	switch {
	case strings.Contains(model, "4bit"):
		return 40
	case strings.Contains(model, "nvfp4"):
		return 30
	case strings.Contains(model, "mlx"):
		return 20
	default:
		return 10
	}
}

func compareQwenRank(aVersion []int, aParams, aVariant int, bVersion []int, bParams, bVariant int) int {
	n := len(aVersion)
	if len(bVersion) > n {
		n = len(bVersion)
	}
	for i := 0; i < n; i++ {
		av, bv := 0, 0
		if i < len(aVersion) {
			av = aVersion[i]
		}
		if i < len(bVersion) {
			bv = bVersion[i]
		}
		if av > bv {
			return 1
		}
		if av < bv {
			return -1
		}
	}
	if aParams != bParams {
		if aParams > bParams {
			return 1
		}
		return -1
	}
	if aVariant > bVariant {
		return 1
	}
	if aVariant < bVariant {
		return -1
	}
	return 0
}

// SameModelIntent returns true if two model strings refer to the same model
// after canonicalization. Used by capability gating and provider matching.
func SameModelIntent(a, b string) bool {
	ca := canonicalizeModelKey(a)
	cb := canonicalizeModelKey(b)
	if ca == "" || cb == "" {
		return false
	}
	return ca == cb || strings.Contains(ca, cb) || strings.Contains(cb, ca)

